mapper.insert:
INSERT INTO sekai_picture_wallpaper (
    user_id, category_id, title, character_name, source_name, tags, image_url,
    file_name, file_size, width, height, color_tone, is_original, download_count, content_hash
) VALUES (
    #{userId}, #{categoryId}, #{title}, #{characterName}, #{sourceName}, #{tags}, #{imageUrl},
    #{fileName}, #{fileSize}, #{width}, #{height}, #{colorTone}, #{original}, #{downloadCount}, #{contentHash}
)

mapper.select:
SELECT FROM sekai_picture_wallpaper w LEFT JOIN sekai_picture_category c ON c.id = w.category_id LEFT JOIN sekai_picture_favorite f ON f.wallpaper_id = w.id AND f.user_id = #{userId}
ORDER BY w.download_count DESC, w.id DESC
ORDER BY (IFNULL(w.width, 0) * IFNULL(w.height, 0)) DESC, w.id DESC
ORDER BY w.title ASC, w.id DESC
ORDER BY w.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM sekai_picture_wallpaper w
LEFT JOIN sekai_picture_favorite f ON f.wallpaper_id = w.id AND f.user_id = #{userId}

SELECT  FROM sekai_picture_wallpaper w
LEFT JOIN sekai_picture_category c ON c.id = w.category_id
LEFT JOIN sekai_picture_favorite f ON f.wallpaper_id = w.id AND f.user_id = #{userId}
 ORDER BY w.id DESC LIMIT #{limit} OFFSET #{offset}
